-- Applied in Supabase as 20260912_player_profile_counts.
BEGIN;
CREATE OR REPLACE FUNCTION public.get_player_profile(p_player_id UUID) RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE v_player RECORD;v_follow_status TEXT;v_followers BIGINT;v_attrs JSONB;v_owner BOOLEAN;v_follower BOOLEAN;
BEGIN SELECT p.id,p.profile_id,p.full_name,p.preferred_name,p.bio,p.date_of_birth,p.position,p.preferred_foot,p.photo_url,p.club_id,p.jersey_number,p.nationality,p.height_cm,p.weight_kg,p.football_passport_no,p.profile_visibility,p.verification_status,p.verified_at,c.name club_name,c.logo_url club_logo INTO v_player FROM public.players p LEFT JOIN public.clubs c ON c.id=p.club_id WHERE p.id=p_player_id AND p.is_active=true;IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','PLAYER_NOT_FOUND');END IF;
v_owner=v_player.profile_id=(SELECT auth.uid());SELECT pf.status INTO v_follow_status FROM public.player_follows pf WHERE pf.player_id=p_player_id AND pf.follower_profile_id=(SELECT auth.uid());v_follower=v_follow_status='approved';SELECT count(*) INTO v_followers FROM public.player_follows WHERE player_id=p_player_id AND status='approved';IF NOT(v_owner OR v_player.profile_visibility='public' OR v_follower) THEN RETURN jsonb_build_object('ok',true,'restricted',true,'player',jsonb_build_object('id',v_player.id,'preferred_name',coalesce(v_player.preferred_name,v_player.full_name),'photo_url',v_player.photo_url,'position',v_player.position,'verification_status',v_player.verification_status,'profile_visibility',v_player.profile_visibility,'follower_count',v_followers),'follow_status',coalesce(v_follow_status,'none'));END IF;
SELECT to_jsonb(a)-'player_id'-'updated_at' INTO v_attrs FROM public.player_attribute_state a WHERE a.player_id=p_player_id;RETURN jsonb_build_object('ok',true,'restricted',false,'player',jsonb_build_object('id',v_player.id,'full_name',v_player.full_name,'preferred_name',coalesce(v_player.preferred_name,v_player.full_name),'bio',v_player.bio,'age',extract(year from age(current_date,v_player.date_of_birth))::integer,'position',v_player.position,'preferred_foot',v_player.preferred_foot,'photo_url',v_player.photo_url,'club_id',v_player.club_id,'club_name',v_player.club_name,'club_logo',v_player.club_logo,'jersey_number',v_player.jersey_number,'nationality',v_player.nationality,'height_cm',v_player.height_cm,'weight_kg',v_player.weight_kg,'football_passport_no',v_player.football_passport_no,'verification_status',v_player.verification_status,'verified_at',v_player.verified_at,'profile_visibility',v_player.profile_visibility,'follower_count',v_followers),'attributes',coalesce(v_attrs,'{}'::jsonb),'follow_status',coalesce(v_follow_status,'none'));END;$$;
REVOKE ALL ON FUNCTION public.get_player_profile(UUID) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.get_player_profile(UUID) TO anon,authenticated;COMMIT;